class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    @store[key] = {
      payload: @packer ? @packer.dump(payload) : payload,
      stale: stale
    }
  end

  def read(key)
    entry = @store[key]
    return nil unless entry
    if @packer
      @packer.load(entry[:payload])
    else
      entry[:payload]
    end
  end

  def sweep
    @store = @store.reject { |_, entry| entry[:stale] }
  end
end
