class Band
  def initialize(min, max)
    raise ArgumentError, "min must be less than max" unless min < max
    @min = min
    @max = max
  end

  def match?(number)
    @min <= number && number < @max
  end

  def case_match?(number)
    match?(number)
  end

  # For use in case/when statements, Ruby calls === on the when clause object
  # with the case value. So we need === to return true when the number matches.
  def ===(number)
    match?(number)
  end
end
