class Proxy
  def initialize(target)
    @target = target
  end

  def method_missing(name, *args, &block)
    if @target.respond_to?(name)
      @target.send(name, *args, &block)
    else
      super
    end
  end

  def respond_to?(name, include_private = false)
    if @target.respond_to?(name, include_private)
      true
    else
      super
    end
  end

  def method(name)
    if @target.respond_to?(name)
      target = self
      ->(*args, &block) {
        target.send(name, *args, &block)
      }
    else
      super
    end
  end
end
