class KeyStore
  def initialize
    @store = {}
  end

  def store(key, value)
    @store[key] = value
  end

  def fetch(key, &block)
    if @store.key?(key)
      @store[key]
    elsif block
      block.call
    else
      nil
    end
  end
end

class TallyingKeyStore < KeyStore
  attr_reader :hits, :misses

  def initialize
    super
    @hits = 0
    @misses = 0
  end

  def fetch(key, &block)
    # We need to determine if the key is already stored to increment hits/misses
    # We access the internal store via a method that doesn't expose it, but we can use instance_variable_get
    # Actually, let's use a cleaner approach: check if key is in store
    stored = instance_variable_get(:@store)
    if stored.key?(key)
      @hits += 1
      stored[key]
    elsif block
      @misses += 1
      block.call
    else
      @misses += 1
      nil
    end
  end
end
```

